import React, { useState, useMemo, useEffect, useRef, useCallback } from "react";
import {
  ShoppingCart, ArrowRight, Plus, Minus, Check, AlertTriangle,
  Truck, Store, X, Package, Banknote, Landmark, Clock, Search, Loader2,
  Star, Send, RotateCcw, Heart, Bell,
} from "lucide-react";
import { api, session } from "./api.js";
import { MapContainer, TileLayer, Marker, useMapEvents } from "react-leaflet";
import { useSession, useFetch, useAction } from "./hooks.js";
import L from "leaflet";
import "leaflet/dist/leaflet.css";

const markerIcon = L.icon({
  iconUrl: "https://unpkg.com/leaflet@1.9.4/dist/images/marker-icon.png",
  iconRetinaUrl: "https://unpkg.com/leaflet@1.9.4/dist/images/marker-icon-2x.png",
  shadowUrl: "https://unpkg.com/leaflet@1.9.4/dist/images/marker-shadow.png",
  iconSize: [25, 41],
  iconAnchor: [12, 41],
  popupAnchor: [1, -34],
  shadowSize: [41, 41],
});


const LOGO_MARK = "data:image/png;base64,";
const LOGO_FULL = "data:image/png;base64,";

const money = (n) => `${Number(n || 0).toFixed(2)} د.ل`;

const PAYMENT_LABELS = {
  cash: "نقدًا عند الاستلام",
  transfer: "حوالة مصرفية",
  deferred: "آجل معتمد من الإدارة",
  card: "بطاقة",
  pay_at_supplier: "الدفع عند المورد",
};

const STATUS_LABELS = {
  draft: "مسودة", under_review: "قيد المراجعة", approved: "معتمدة",
  sent_to_supplier: "مرسلة إلى المورد", supplier_preparing: "قيد التجهيز",
  shortage: "يوجد نقص", ready_for_delivery: "جاهزة للتوصيل",
  ready_for_pickup: "جاهزة للاستلام", assigned_to_driver: "جاهزة للتوصيل",
  out_for_delivery: "في الطريق", awaiting_pickup: "بانتظار الاستلام",
  delivered: "تم التسليم", closed: "مقفولة", postponed: "مؤجلة", cancelled: "ملغاة",
};
const statusLabel = (s) => STATUS_LABELS[s] || s;

// تبسيط الحالات الداخلية الكتيرة لمجموعة صغيرة يفهمها العميل العادي —
// تُستخدم في قوائم الطلبيات وشارة الحالة وسجل الحالة، بدل التفاصيل الداخلية
const CUSTOMER_STATUS_GROUPS = {
  draft: "قيد التجهيز", under_review: "قيد التجهيز", sent_to_supplier: "قيد التجهيز",
  supplier_preparing: "قيد التجهيز", shortage: "قيد التجهيز",
  ready_for_delivery: "جاهزة للتوصيل", assigned_to_driver: "جاهزة للتوصيل",
  ready_for_pickup: "جاهزة للاستلام",
  out_for_delivery: "في الطريق إليك", awaiting_pickup: "بانتظار استلامك",
  delivered: "تم التسليم", closed: "تم التسليم",
  postponed: "مؤجلة", cancelled: "ملغاة",
};
const customerStatusLabel = (s) => CUSTOMER_STATUS_GROUPS[s] || statusLabel(s);

/* ===================================================================
   الجذر
=================================================================== */

export default function JomlaCustomerApp() {
  const { actor, profile, loading, requestOtp, verifyOtp, logout } = useSession("customer");
  const [view, setView] = useState("home");
  const [activeSection, setActiveSection] = useState(null);
  const [supplierFilter, setSupplierFilter] = useState("all");
  const [selectedOrderId, setSelectedOrderId] = useState(null);
  const [cart, setCart] = useState({});          // { productId: { product, qty } }
  const [banner, setBanner] = useState(null);
  const [toast, setToast] = useState(null);

  const favorites = useFetch(() => (actor ? api.favorites() : Promise.resolve([])), [actor?.id]);
  const favIds = useMemo(() => new Set((favorites.data ?? []).map((p) => p.id)), [favorites.data]);
  const toggleFavorite = useCallback((product) => {
    const action = favIds.has(product.id) ? api.removeFavorite(product.id) : api.addFavorite(product.id);
    action.then(favorites.reload).catch(() => {});
  }, [favIds, favorites]);

  const sections = profile?.sections ?? [];

  const cartItems = useMemo(() => Object.values(cart).filter((i) => i.qty > 0), [cart]);
  const cartCount = cartItems.reduce((s, i) => s + i.qty, 0);
  const cartSuppliers = [...new Set(cartItems.map((i) => i.product.supplier_id))];

  const showToast = useCallback((msg) => {
    setToast(msg);
    window.clearTimeout(window.__jomlaToast);
    window.__jomlaToast = window.setTimeout(() => setToast(null), 1800);
  }, []);

  function addToCart(product) {
    const isNewSupplier = cartSuppliers.length > 0 && !cartSuppliers.includes(product.supplier_id);
    setCart((c) => ({
      ...c,
      [product.id]: { product, qty: (c[product.id]?.qty || 0) + 1 },
    }));
    showToast(`أُضيف «${product.name}» إلى السلة`);
    if (isNewSupplier) {
      setBanner("طلبيتك أصبحت من أكثر من مورد — ستُقسَّم إلى فواتير منفصلة وقد تزيد تكلفة التوصيل.");
    }
  }

  function changeQty(productId, delta) {
    setCart((c) => {
      const entry = c[productId];
      if (!entry) return c;
      const qty = Math.max(0, entry.qty + delta);
      if (qty === 0) { const { [productId]: _, ...rest } = c; return rest; }
      return { ...c, [productId]: { ...entry, qty } };
    });
  }

  function resetAfterOrder() {
    setCart({});
    setBanner(null);
    setActiveSection(null);
    setSupplierFilter("all");
    setView("orders");
  }

  if (loading) return <FullScreenLoader />;
    if (!actor) {
    return (
      <Shell>
        <AuthGate onRequestOtp={requestOtp} onVerify={verifyOtp} />
      </Shell>
    );
  }


  return (
    <Shell>
      <TopBar
        view={view}
        cartCount={cartCount}
        onBack={() => {
          if (view === "section") setView("home");
          else if (view === "cart") setView(activeSection ? "section" : "home");
          else if (view === "checkout") setView("cart");
          else if (view === "orderDetail") setView("orders");
          else if (view === "favorites") setView("home");
          else setView("home");
        }}
        onHome={() => setView("home")}
        onCart={() => setView("cart")}
        onOrders={() => setView("orders")}
        onLogout={logout}
      />

      <main className="jomla-main">
        {view === "home" && (
          <HomeView
            actorName={actor.name}
            sections={sections}
            cart={cart}
            onAdd={addToCart}
            onChangeQty={changeQty}
            onOpenSection={(id) => { setActiveSection(id); setSupplierFilter("all"); setView("section"); }}
            onOrders={() => setView("orders")}
            onFavorites={() => setView("favorites")}
            favIds={favIds}
            onToggleFavorite={toggleFavorite}
          />
        )}

        {view === "section" && (
          <SectionView
            sectionId={activeSection}
            sectionName={sections.find((s) => s.id === activeSection)?.name}
            supplierFilter={supplierFilter}
            setSupplierFilter={setSupplierFilter}
            cart={cart}
            onAdd={addToCart}
            onChangeQty={changeQty}
            favIds={favIds}
            onToggleFavorite={toggleFavorite}
          />
        )}

        {view === "favorites" && (
          <FavoritesView
            favorites={favorites}
            cart={cart}
            onAdd={addToCart}
            onChangeQty={changeQty}
            onToggleFavorite={toggleFavorite}
            onShop={() => setView("home")}
          />
        )}

        {view === "cart" && (
          <CartView
            items={cartItems}
            onChangeQty={changeQty}
            onCheckout={() => setView("checkout")}
            onShop={() => setView("home")}
          />
        )}

        {view === "checkout" && (
          <CheckoutView
            items={cartItems}
            onDone={(order) => { resetAfterOrder(); showToast(`تم إرسال الطلبية ${order.order_number} للمراجعة`); }}
            onBack={() => setView("cart")}
          />
        )}

        {view === "orders" && (
          <OrdersView
            customerId={actor.id}
            onOpenOrder={(id) => { setSelectedOrderId(id); setView("orderDetail"); }}
            onShop={() => setView("home")}
          />
        )}

        {view === "orderDetail" && (
          <OrderDetailView orderId={selectedOrderId} />
        )}
      </main>

      {banner && (view === "section" || view === "cart") && (
        <div className="jomla-banner">
          <AlertTriangle size={16} />
          <span>{banner}</span>
          <button onClick={() => setBanner(null)} aria-label="إغلاق"><X size={14} /></button>
        </div>
      )}

      {toast && <div className="jomla-toast">{toast}</div>}

      {cartCount > 0 && (view === "section" || view === "home" || view === "favorites") && (
        <button className="jomla-fab" onClick={() => setView("cart")}>
          <ShoppingCart size={18} /><span>عرض السلة</span><b>{cartCount}</b>
        </button>
      )}
    </Shell>
  );
}

/* ===================================================================
   عناصر مشتركة
=================================================================== */

const Shell = ({ children }) => (
  <div dir="rtl" lang="ar" className="jomla-root"><Style />{children}</div>
);

const FullScreenLoader = () => (
  <Shell>
    <div className="center-state"><Loader2 className="spin" size={26} /><p>جارٍ التحميل…</p></div>
  </Shell>
);

const Spinner = ({ label = "جارٍ التحميل…" }) => (
  <div className="center-state"><Loader2 className="spin" size={22} /><p>{label}</p></div>
);

const ErrorState = ({ message, onRetry }) => (
  <div className="center-state">
    <AlertTriangle size={22} />
    <p>{message}</p>
    {onRetry && <button className="btn-ghost" onClick={onRetry}>إعادة المحاولة</button>}
  </div>
);

function BrandMark({ size = 24 }) {
  return <img src={LOGO_MARK} alt="جملة" style={{ height: size, width: "auto", display: "block" }} />;
}

/* ===================================================================
   تسجيل الدخول
=================================================================== */

function AuthGate({ onRequestOtp, onVerify }) {
  const [mode, setMode] = useState("login"); // login | register | pending

  if (mode === "register") {
    return <RegisterView onDone={() => setMode("pending")} onCancel={() => setMode("login")} />;
  }
  if (mode === "pending") {
    return <PendingApprovalView onBack={() => setMode("login")} />;
  }
  return <LoginView onRequestOtp={onRequestOtp} onVerify={onVerify} onNewAccount={() => setMode("register")} />;
}

function PendingApprovalView({ onBack }) {
  return (
    <div className="login-screen">
      <BrandMark size={64} />
      <p className="login-sub">تجارة الجملة — سوق الجمعة، طرابلس</p>
      <div className="login-card" style={{ textAlign: "center" }}>
        <Clock size={40} style={{ margin: "0 auto 14px", display: "block", opacity: 0.7 }} />
        <p style={{ fontWeight: 700, marginBottom: 8 }}>طلبك قيد المراجعة</p>
        <p className="hint" style={{ marginBottom: 20 }}>
          تم استلام طلب تسجيل حسابك بنجاح. سيتم التواصل معك بعد اعتماد الحساب من إدارة جملة.
        </p>
        <button className="btn-ghost" onClick={onBack}>رجوع لتسجيل الدخول</button>
      </div>
    </div>
  );
}

function RegisterView({ onDone, onCancel }) {
  const [form, setForm] = useState({ name: "", phone: "", address: "" });
  const [businessTypes, setBusinessTypes] = useState([""]);
  const [location, setLocation] = useState(null);
  const set = (k) => (e) => setForm((f) => ({ ...f, [k]: e.target.value }));

  const submit = useAction(() => api.registerAccount("customer", {
    businessName: form.name.trim(),
    phone: form.phone.trim(),
    address: form.address.trim() || undefined,
    latitude: location?.lat,
    longitude: location?.lng,
    businessTypes: businessTypes.map((t) => t.trim()).filter(Boolean),
  }));

  const valid = form.name.trim() && form.phone.replace(/\D/g, "").length >= 9;

  return (
    <div className="login-screen">
      <BrandMark size={64} />
      <p className="login-sub">إنشاء حساب عميل جديد</p>
      <div className="login-card">
        <label className="field-label">اسم النشاط أو المتجر</label>
        <input className="field-input" value={form.name} onChange={set("name")} />

        <label className="field-label">رقم الهاتف</label>
        <input className="field-input" value={form.phone} onChange={set("phone")}
          dir="ltr" style={{ textAlign: "right" }} inputMode="numeric" placeholder="09XXXXXXXX" />

        <label className="field-label">العنوان</label>
        <input className="field-input" value={form.address} onChange={set("address")} />

        <label className="field-label">نوع النشاط</label>
        {businessTypes.map((t, i) => (
          <div key={i} style={{ display: "flex", gap: 8, marginBottom: 12 }}>
            <input className="field-input" style={{ marginBottom: 0, flex: 1 }} value={t}
              placeholder="مثال: مواد بناء"
              onChange={(e) => setBusinessTypes((arr) => arr.map((v, idx) => idx === i ? e.target.value : v))} />
            {businessTypes.length > 1 && (
              <button type="button" className="btn-ghost" style={{ width: "auto", padding: "0 14px", marginBottom: 0 }}
                onClick={() => setBusinessTypes((arr) => arr.filter((_, idx) => idx !== i))}>−</button>
            )}
            {i === businessTypes.length - 1 && (
              <button type="button" className="btn-ghost" style={{ width: "auto", padding: "0 14px", marginBottom: 0 }}
                onClick={() => setBusinessTypes((arr) => [...arr, ""])}>+</button>
            )}
          </div>
        ))}


        <label className="field-label">تحديد الموقع على الخريطة</label>
        <RegisterLocationPicker value={location} onChange={setLocation} />

        {submit.error && <p className="field-error">{submit.error}</p>}

        <button className="btn-primary" disabled={!valid || submit.pending}
          onClick={() => submit.run().then(onDone).catch(() => {})}>
          {submit.pending ? "جارٍ الإرسال…" : "إرسال طلب التسجيل"}
        </button>
        <button className="btn-ghost" onClick={onCancel}>إلغاء</button>
      </div>
    </div>
  );
}

function RegisterLocationPicker({ value, onChange }) {
  const TRIPOLI_CENTER = [32.8872, 13.1913];
  function ClickHandler() {
    useMapEvents({
      click(e) {
        onChange({ lat: Number(e.latlng.lat.toFixed(5)), lng: Number(e.latlng.lng.toFixed(5)) });
      },
    });
    return null;
  }
  return (
    <div className="map-picker-wrap">
      <div className="map-picker">
        <MapContainer
          center={value ? [value.lat, value.lng] : TRIPOLI_CENTER}
          zoom={value ? 15 : 12}
          style={{ height: "220px", width: "100%" }}
        >
          <TileLayer attribution='&copy; OpenStreetMap contributors'
            url="https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png" />
          <ClickHandler />
          {value && <Marker position={[value.lat, value.lng]} icon={markerIcon} />}
        </MapContainer>
        {!value && <div className="map-hint">اضغط على الخريطة لتحديد الموقع</div>}
      </div>
      {value && (
        <div className="map-coords">
          <span>الإحداثيات: {value.lat}, {value.lng}</span>
          <button className="link-btn" onClick={() => onChange(null)}>مسح الموقع</button>
        </div>
      )}
    </div>
  );
}


function LoginView({ onRequestOtp, onVerify, onNewAccount }) {
  const [step, setStep] = useState("phone");
  const [phone, setPhone] = useState("");
  const [digits, setDigits] = useState(["", "", "", ""]);
  const [seconds, setSeconds] = useState(0);
  const inputsRef = useRef([]);

  const send = useAction(onRequestOtp);
  const verify = useAction(onVerify);

  useEffect(() => {
    if (step !== "otp" || seconds <= 0) return;
    const t = setTimeout(() => setSeconds((s) => s - 1), 1000);
    return () => clearTimeout(t);
  }, [step, seconds]);

  useEffect(() => { if (step === "otp") inputsRef.current[0]?.focus(); }, [step]);

  async function handleSend() {
    if (phone.replace(/\D/g, "").length < 9) return;
    await send.run(phone);
    setSeconds(30);
    setStep("otp");
  }

  function updateDigit(i, val) {
    const v = val.replace(/\D/g, "").slice(-1);
    const next = [...digits]; next[i] = v; setDigits(next);
    if (v && i < 3) inputsRef.current[i + 1]?.focus();
  }
  function handlePaste(e) {
    const text = e.clipboardData.getData("text").replace(/\D/g, "");
    if (!text) return;
    e.preventDefault();
    const next = [...digits];
    for (let i = 0; i < 4; i++) next[i] = text[i] || next[i];
    setDigits(next);
    inputsRef.current[Math.min(text.length, 4) - 1]?.focus();
  }

  return (
    <div className="screen login-screen">
      <div className="brand-row"><img src={LOGO_FULL} alt="جملة" className="brand-logo-full" /></div>
      <p className="login-sub">منصة تجارة الجملة — سوق الجمعة، طرابلس</p>

      {step === "phone" ? (
        <div className="login-card">
          <label className="field-label">رقم الحساب المعتمد</label>
          <input
            className="field-input" placeholder="09XXXXXXXX" value={phone}
            onChange={(e) => setPhone(e.target.value)} dir="ltr"
            style={{ textAlign: "right" }} inputMode="numeric"
            onKeyDown={(e) => e.key === "Enter" && handleSend()}
          />
          {send.error && <p className="field-error">{send.error}</p>}
          <button className="btn-primary" onClick={handleSend} disabled={send.pending}>
            {send.pending ? "جارٍ الإرسال…" : "إرسال رمز التحقق"}
          </button>
          <p className="login-note">الدخول متاح للمحلات المعتمدة من إدارة جملة</p>
<button className="link-btn" onClick={onNewAccount}>مستخدم جديد؟ أنشئ حسابك من هنا</button>

        </div>
      ) : (
        <div className="login-card">
          <label className="field-label">رمز التحقق المُرسل إلى {phone}</label>
          <div className="otp-row" dir="ltr">
            {digits.map((d, i) => (
              <input
                key={i} ref={(el) => (inputsRef.current[i] = el)} className="otp-box"
                value={d} onChange={(e) => updateDigit(i, e.target.value)}
                onKeyDown={(e) => e.key === "Backspace" && !digits[i] && i > 0 && inputsRef.current[i - 1]?.focus()}
                onPaste={handlePaste} onFocus={(e) => e.target.select()}
                type="tel" inputMode="numeric" maxLength={1}
                autoComplete={i === 0 ? "one-time-code" : "off"}
              />
            ))}
          </div>
          {verify.error && <p className="field-error">{verify.error}</p>}
          <button
            className="btn-primary"
            disabled={verify.pending || digits.join("").length < 4}
            onClick={() => verify.run(phone, digits.join("")).catch(() => {})}
          >
            {verify.pending ? "جارٍ التحقق…" : "تأكيد الدخول"}
          </button>
          <div className="otp-footer">
            <button className="link-btn" onClick={() => setStep("phone")}>تعديل الرقم</button>
            <button className="link-btn" disabled={seconds > 0} onClick={handleSend}>
              {seconds > 0 ? `إعادة الإرسال بعد ${seconds} ث` : "إعادة إرسال الرمز"}
            </button>
          </div>
        </div>
      )}
    </div>
  );
}

/* ===================================================================
   الشريط العلوي
=================================================================== */

function NotificationBell() {
  const [open, setOpen] = useState(false);
  const { data, loading, reload } = useFetch(() => api.notifications(), []);

  useEffect(() => {
    const t = setInterval(reload, 30000);
    return () => clearInterval(t);
  }, []);

  const unreadCount = data?.unreadCount ?? 0;

  function markRead(n) {
    if (n.in_app_read_at) return;
    api.markNotificationRead(n.id).then(reload).catch(() => {});
  }
  function markAll() {
    api.markAllNotificationsRead().then(reload).catch(() => {});
  }

  return (
    <div style={{ position: "relative" }}>
      <button className="icon-btn" onClick={() => setOpen((o) => !o)} aria-label="الإشعارات">
        <Bell size={19} />
        {unreadCount > 0 && <span className="notif-badge">{unreadCount > 9 ? "9+" : unreadCount}</span>}
      </button>
      {open && (
        <div className="notif-panel">
          <div className="notif-panel-head">
            <span>الإشعارات</span>
            {unreadCount > 0 && <button className="link-btn" onClick={markAll}>تعليم الكل كمقروء</button>}
          </div>
          {loading ? <Spinner /> : !data?.notifications?.length ? (
            <p className="chat-empty">لا توجد إشعارات بعد</p>
          ) : (
            <div className="notif-list">
              {data.notifications.map((n) => (
                <div key={n.id} className={"notif-row" + (!n.in_app_read_at ? " notif-row-unread" : "")}
                  onClick={() => markRead(n)}>
                  <span className="notif-title">{n.title}</span>
                  <span className="notif-body">{n.body}</span>
                  <span className="notif-time">{new Date(n.created_at).toLocaleString("ar")}</span>
                </div>
              ))}
            </div>
          )}
        </div>
      )}
    </div>
  );
}

function TopBar({ view, cartCount, onBack, onHome, onCart, onOrders, onLogout }) {
  const titles = { section: "الأصناف", cart: "السلة", checkout: "إتمام الطلب", orders: "كشف الحساب", orderDetail: "تفاصيل الطلبية", favorites: "المفضلة" };
  const showBack = view !== "home";
  return (
    <header className="topbar">
      <div className="topbar-row">
        {showBack ? (
          <button className="icon-btn" onClick={onBack} aria-label="رجوع"><ArrowRight size={20} /></button>
        ) : (
          <button className="brand-chip" onClick={onHome}><BrandMark size={22} /><span>جملة</span></button>
        )}
        {showBack && <span className="topbar-title">{titles[view]}</span>}
        <div className="topbar-actions">
          <button className="icon-btn" onClick={onOrders} aria-label="كشف الحساب"><Package size={19} /></button>
          <button className="icon-btn cart-btn" onClick={onCart} aria-label="السلة">
            <ShoppingCart size={19} />
            {cartCount > 0 && <span className="cart-badge">{cartCount}</span>}
          </button>
          <NotificationBell />
          <button className="icon-btn" onClick={onLogout} aria-label="خروج"><X size={18} /></button>
        </div>
      </div>
    </header>
  );
}

/* ===================================================================
   الرئيسية — بحث + الأقسام
=================================================================== */

function HomeView({ actorName, sections, cart, onAdd, onChangeQty, onOpenSection, onOrders, onFavorites, favIds, onToggleFavorite }) {
  const [query, setQuery] = useState("");
  const [debounced, setDebounced] = useState("");

  useEffect(() => {
    const t = setTimeout(() => setDebounced(query.trim()), 350);
    return () => clearTimeout(t);
  }, [query]);

  // البحث يمر على كل قسم مسموح به — الخادم يمنع ما عداها
  const { data: results, loading, error } = useFetch(
    async (signal) => {
      const all = await Promise.all(
        sections.map((s) => api.products({ sectionId: s.id, search: debounced }, signal).catch(() => []))
      );
      return all.flat();
    },
    [debounced, sections.length],
    { skip: !debounced }
  );

  return (
    <div className="screen">
      <p className="eyebrow-plain">مرحبًا، {actorName}</p>

      <div className="search-bar">
        <Search size={16} />
        <input placeholder="ابحث عن صنف أو مورد..." value={query} onChange={(e) => setQuery(e.target.value)} />
        {query && <button className="search-clear" onClick={() => setQuery("")} aria-label="مسح"><X size={15} /></button>}
      </div>

      {debounced ? (
        loading ? <Spinner label="جارٍ البحث…" />
        : error ? <ErrorState message={error} />
        : results?.length ? (
          <div className="product-list">
            {results.map((p) => (
              <ProductRow key={p.id} product={p} qty={cart[p.id]?.qty || 0} onAdd={onAdd} onChangeQty={onChangeQty}
                isFavorite={favIds.has(p.id)} onToggleFavorite={onToggleFavorite} />
            ))}
          </div>
        ) : <div className="center-state"><Search size={22} /><p>لا توجد نتائج مطابقة</p></div>
      ) : (
        <>
          <h2 className="subsection-heading">الأقسام المتاحة لحسابك</h2>
          {sections.length === 0 ? (
            <div className="center-state">
              <Package size={22} />
              <p>لم تُخصَّص لك أقسام بعد — تواصل مع إدارة جملة</p>
            </div>
          ) : (
            <div className="ledger-list">
              {sections.map((s) => (
                <button key={s.id} className="ledger-row" onClick={() => onOpenSection(s.id)}>
                  <div className="ledger-row-accent" />
                  <span className="ledger-row-title">{s.name}</span>
                  <ChevLeft />
                </button>
              ))}
            </div>
          )}
          <button className="past-orders-link" onClick={onOrders}>
            <Clock size={15} /> كشف حسابي ومديونيتي
          </button>
          <button className="past-orders-link" onClick={onFavorites}>
            <Heart size={15} /> الأصناف المفضلة
          </button>
        </>
      )}
    </div>
  );
}

const ChevLeft = () => (
  <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.2">
    <path d="M15 6l-6 6 6 6" strokeLinecap="round" strokeLinejoin="round" />
  </svg>
);

/* ===================================================================
   تصفح القسم
=================================================================== */

function SectionView({ sectionId, sectionName, supplierFilter, setSupplierFilter, cart, onAdd, onChangeQty, favIds, onToggleFavorite }) {
  const { data: suppliers } = useFetch((signal) => api.suppliers(signal), []);
  const { data: products, loading, error, reload } = useFetch(
    (signal) => api.products({
      sectionId,
      supplierId: supplierFilter === "all" ? undefined : supplierFilter,
    }, signal),
    [sectionId, supplierFilter]
  );

  const sectionSuppliers = (suppliers ?? []).filter((s) => s.section_id === sectionId);

  return (
    <div className="screen">
      <h2 className="section-heading">{sectionName}</h2>

      <div className="chip-row">
        <button className={"chip" + (supplierFilter === "all" ? " chip-active" : "")} onClick={() => setSupplierFilter("all")}>
          كل الموردين
        </button>
        {sectionSuppliers.map((s) => (
          <button key={s.id} className={"chip" + (supplierFilter === s.id ? " chip-active" : "")} onClick={() => setSupplierFilter(s.id)}>
            {s.name}
          </button>
        ))}
      </div>

      {loading ? <Spinner />
       : error ? <ErrorState message={error} onRetry={reload} />
       : !products?.length ? <div className="center-state"><Package size={22} /><p>لا توجد أصناف</p></div>
       : (
        <div className="product-list">
          {products.map((p) => (
            <ProductRow key={p.id} product={p} qty={cart[p.id]?.qty || 0} onAdd={onAdd} onChangeQty={onChangeQty}
              isFavorite={favIds?.has(p.id)} onToggleFavorite={onToggleFavorite} />
          ))}
        </div>
      )}
    </div>
  );
}

function ProductRow({ product: p, qty, onAdd, onChangeQty, isFavorite, onToggleFavorite }) {
  const out = p.availability === "out";
  return (
    <div className="product-row">
      <div className="product-thumb">
        {p.image_url ? <img src={p.image_url} alt="" /> : <Package size={20} />}
      </div>
      <div className="product-info">
        <div className="product-name-row">
          <span className="product-name">{p.name}</span>
          {onToggleFavorite && (
            <button className={"fav-btn" + (isFavorite ? " fav-btn-active" : "")}
              onClick={() => onToggleFavorite(p)} aria-label="المفضلة">
              <Heart size={14} fill={isFavorite ? "currentColor" : "none"} />
            </button>
          )}
        </div>
        <span className="product-meta">{p.supplier_name} · {p.unit}</span>
        {p.availability === "low" && <span className="tag tag-amber">كمية محدودة</span>}
        {out && <span className="tag tag-muted">غير متوفر حاليًا</span>}
      </div>
      <div className="product-side">
        <span className="product-price">{money(p.price ?? p.base_price)}</span>
        {out ? <span className="out-label">—</span>
         : qty > 0 ? (
          <div className="stepper">
            <button onClick={() => onChangeQty(p.id, -1)} aria-label="إنقاص"><Minus size={14} /></button>
            <b>{qty}</b>
            <button onClick={() => onChangeQty(p.id, 1)} aria-label="زيادة"><Plus size={14} /></button>
          </div>
        ) : (
          <button className="add-btn" onClick={() => onAdd(p)}><Plus size={14} />أضف</button>
        )}
      </div>
    </div>
  );
}

function FavoritesView({ favorites, cart, onAdd, onChangeQty, onToggleFavorite, onShop }) {
  const { data, loading, error, reload } = favorites;
  return (
    <div className="screen">
      <h2 className="section-heading">الأصناف المفضلة</h2>
      {loading ? <Spinner />
       : error ? <ErrorState message={error} onRetry={reload} />
       : !data?.length ? (
        <div className="center-state">
          <Heart size={24} /><p>لم تُضف أصنافًا للمفضلة بعد</p>
          <button className="btn-primary" onClick={onShop}>تصفح الأقسام</button>
        </div>
      ) : (
        <div className="product-list">
          {data.map((p) => (
            <ProductRow key={p.id} product={p} qty={cart[p.id]?.qty || 0} onAdd={onAdd} onChangeQty={onChangeQty}
              isFavorite onToggleFavorite={onToggleFavorite} />
          ))}
        </div>
      )}
    </div>
  );
}

/* ===================================================================
   السلة
=================================================================== */

function groupBySupplier(items) {
  const ids = [...new Set(items.map((i) => i.product.supplier_id))];
  return ids.map((id) => {
    const mine = items.filter((i) => i.product.supplier_id === id);
    return {
      supplierId: id,
      supplierName: mine[0].product.supplier_name,
      items: mine,
      subtotal: mine.reduce((s, i) => s + (i.product.price ?? i.product.base_price) * i.qty, 0),
    };
  });
}

function CartView({ items, onChangeQty, onCheckout, onShop }) {
  if (!items.length) {
    return (
      <div className="screen center-state">
        <ShoppingCart size={28} /><p>سلتك فارغة حاليًا</p>
        <button className="btn-primary" onClick={onShop}>تصفح الأقسام</button>
      </div>
    );
  }
  const groups = groupBySupplier(items);
  const subtotal = groups.reduce((s, g) => s + g.subtotal, 0);

  return (
    <div className="screen">
      <h2 className="section-heading">
        سلتك — {groups.length > 1 ? `${groups.length} موردين` : "مورد واحد"}
      </h2>

      {groups.map((g) => (
        <div className="invoice-block" key={g.supplierId}>
          <div className="invoice-head">
            <span>{g.supplierName}</span>
            <span className="invoice-head-count">{g.items.reduce((s, i) => s + i.qty, 0)} قطعة</span>
          </div>
          {g.items.map(({ product, qty }) => (
            <div className="invoice-line" key={product.id}>
              <span className="invoice-line-name">{product.name}</span>
              <div className="stepper stepper-sm">
                <button onClick={() => onChangeQty(product.id, -1)} aria-label="إنقاص"><Minus size={12} /></button>
                <b>{qty}</b>
                <button onClick={() => onChangeQty(product.id, 1)} aria-label="زيادة"><Plus size={12} /></button>
              </div>
              <span className="invoice-line-price">{money((product.price ?? product.base_price) * qty)}</span>
            </div>
          ))}
          <div className="invoice-sub">
            <span>مجموع فاتورة {g.supplierName}</span><b>{money(g.subtotal)}</b>
          </div>
        </div>
      ))}

      <div className="grand-row"><span>المجموع قبل التوصيل</span><b>{money(subtotal)}</b></div>
      <button className="btn-primary" onClick={onCheckout}>متابعة إلى الدفع والتوصيل</button>
    </div>
  );
}

/* ===================================================================
   إتمام الطلب — يرسل للخادم فعليًا
=================================================================== */

function CheckoutView({ items, onDone, onBack }) {
  const [fulfillment, setFulfillment] = useState("delivery");
  const [paymentMethod, setPaymentMethod] = useState("cash");
  const [notes, setNotes] = useState({});   // { supplierId: "ملاحظة" }
  const [deliveryZoneId, setDeliveryZoneId] = useState("");
  const [vehicleTypeId, setVehicleTypeId] = useState("");
  const [vehiclesCount, setVehiclesCount] = useState(1);

  const zones = useFetch((s) => api.deliveryZones(s), []);
  const vehicleTypes = useFetch((s) => api.vehicleTypes(s), []);
  const activeZones = (zones.data ?? []).filter((z) => z.is_active !== false);
  const activeVehicleTypes = (vehicleTypes.data ?? []).filter((v) => v.is_active !== false);

  const groups = groupBySupplier(items);
  const subtotal = groups.reduce((s, g) => s + g.subtotal, 0);

  const submit = useAction(() =>
    api.createOrder({
      fulfillment,
      paymentMethod,
      deliveryZoneId: fulfillment === "delivery" ? (deliveryZoneId || undefined) : undefined,
      vehicleTypeId: fulfillment === "delivery" ? (vehicleTypeId || undefined) : undefined,
      vehiclesCount: fulfillment === "delivery" ? vehiclesCount : 1,
      supplierNotes: notes,
      items: items.map((i) => ({ productId: i.product.id, qty: i.qty })),
    })
  );

  const pickupOnly = fulfillment === "pickup";
  const deliveryReady = pickupOnly || (deliveryZoneId && vehicleTypeId);

  return (
    <div className="screen">
      <h2 className="section-heading">التوصيل والاستلام</h2>
      <div className="tile-row">
        <button className={"tile" + (fulfillment === "delivery" ? " tile-active" : "")} onClick={() => setFulfillment("delivery")}>
          <Truck size={20} /><span>توصيل داخل طرابلس</span>
        </button>
        <button className={"tile" + (pickupOnly ? " tile-active" : "")} onClick={() => setFulfillment("pickup")}>
          <Store size={20} /><span>استلام شخصي</span>
        </button>
      </div>
      <p className="hint">
        {pickupOnly
          ? "الاستلام الشخصي يتطلب الدفع مسبقًا بحوالة مؤكدة أو الدفع الكامل عند المورد."
          : "تُحتسب تكلفة التوصيل من الإدارة حسب المنطقة ونوع السيارة وعدد الموردين، وتظهر في الفاتورة."}
      </p>

      {!pickupOnly && (
        <>
          <h2 className="section-heading" style={{ marginTop: 22 }}>منطقة التوصيل</h2>
          {zones.loading ? <Spinner /> : (
            <div className="tile-row" style={{ flexWrap: "wrap" }}>
              {activeZones.map((z) => (
                <button key={z.id} className={"tile" + (deliveryZoneId === z.id ? " tile-active" : "")}
                  onClick={() => setDeliveryZoneId(z.id)}>
                  <span>{z.name}</span>
                </button>
              ))}
              {!activeZones.length && <p className="hint">لا توجد مناطق توصيل متاحة حاليًا</p>}
            </div>
          )}

          <h2 className="section-heading" style={{ marginTop: 22 }}>نوع السيارة</h2>
          {vehicleTypes.loading ? <Spinner /> : (
            <div className="tile-row" style={{ flexWrap: "wrap" }}>
              {activeVehicleTypes.map((v) => (
                <button key={v.id} className={"tile" + (vehicleTypeId === v.id ? " tile-active" : "")}
                  onClick={() => setVehicleTypeId(v.id)}>
                  <Truck size={18} />
                  <span>{v.name}</span>
                  {(v.max_weight_kg || v.max_volume_m3) && (
                    <i style={{ fontSize: 11, display: "block", marginTop: 2 }}>
                      {v.max_weight_kg ? `حتى ${v.max_weight_kg} كغم` : ""}
                      {v.max_weight_kg && v.max_volume_m3 ? " · " : ""}
                      {v.max_volume_m3 ? `${v.max_volume_m3} م³` : ""}
                    </i>
                  )}
                </button>
              ))}
              {!activeVehicleTypes.length && <p className="hint">لا توجد أنواع سيارات متاحة حاليًا</p>}
            </div>
          )}

          {vehicleTypeId && (
            <div className="stock-row" style={{ marginTop: 12 }}>
              <span className="stock-current">عدد السيارات</span>
              <div className="stock-actions">
                <button className="chip" onClick={() => setVehiclesCount((n) => Math.max(1, n - 1))}>−</button>
                <span style={{ minWidth: 24, textAlign: "center", display: "inline-block" }}>{vehiclesCount}</span>
                <button className="chip" onClick={() => setVehiclesCount((n) => n + 1)}>+</button>
              </div>
            </div>
          )}
        </>
      )}

      <h2 className="section-heading" style={{ marginTop: 22 }}>طريقة الدفع</h2>
      <div className="pay-list">
        <PayOption id="cash" icon={<Banknote size={18} />} label="نقدًا عند الاستلام"
          value={paymentMethod} onChange={setPaymentMethod} disabled={pickupOnly} />
        <PayOption id="transfer" icon={<Landmark size={18} />} label="حوالة مصرفية"
          value={paymentMethod} onChange={setPaymentMethod} />
        <PayOption id="deferred" icon={<Clock size={18} />} label="آجل (يتطلب اعتماد الإدارة)"
          value={paymentMethod} onChange={setPaymentMethod} />
      </div>

      <h2 className="section-heading" style={{ marginTop: 22 }}>ملاحظات للموردين</h2>
      {groups.map((g) => (
        <div className="supplier-note-block" key={g.supplierId}>
          <label className="field-label">ملاحظة لـ{g.supplierName}</label>
          <textarea
            className="note-input" placeholder="مثال: التغليف بعناية، التسليم صباحًا"
            value={notes[g.supplierId] || ""}
            onChange={(e) => setNotes((n) => ({ ...n, [g.supplierId]: e.target.value }))}
          />
        </div>
      ))}

      <div className="summary-block">
        <div className="summary-row">
          <span>مجموع الأصناف ({groups.length} {groups.length > 1 ? "فواتير" : "فاتورة"})</span>
          <span>{money(subtotal)}</span>
        </div>
        <div className="summary-row summary-total">
          <span>الإجمالي قبل التوصيل</span><b>{money(subtotal)}</b>
        </div>
      </div>

      {submit.error && <p className="field-error">{submit.error}</p>}

      <button
        className="btn-primary"
        disabled={submit.pending || !deliveryReady}
        onClick={() => submit.run().then(onDone).catch(() => {})}
      >
        {submit.pending ? "جارٍ الإرسال…"
          : !deliveryReady ? "اختر منطقة ونوع السيارة أولًا"
          : "تأكيد الطلب وإرساله للمراجعة"}
      </button>
      <button className="btn-ghost" onClick={onBack}>رجوع للسلة</button>
      <p className="hint hint-center">
        لن تصل طلبيتك للموردين مباشرة — تمر أولًا بمراجعة داخلية من فريق جملة.
      </p>
    </div>
  );
}

function PayOption({ id, icon, label, value, onChange, disabled }) {
  return (
    <button
      className={"pay-option" + (value === id ? " pay-active" : "") + (disabled ? " pay-disabled" : "")}
      onClick={() => !disabled && onChange(id)} disabled={disabled}
    >
      <span className="pay-icon">{icon}</span>
      <span className="pay-label">{label}</span>
      <span className="pay-radio">{value === id && !disabled && <Check size={13} />}</span>
    </button>
  );
}

/* ===================================================================
   كشف الحساب
=================================================================== */

function OrdersView({ customerId, onOpenOrder, onShop }) {
  const [tab, setTab] = useState("orders");
  const [query, setQuery] = useState("");

  const orders = useFetch((signal) => api.orders(undefined, signal), []);
  const ledger = useFetch((signal) => api.customerLedger(customerId, signal), [customerId], { skip: tab !== "ledger" });

  const filtered = (orders.data ?? []).filter(
    (o) => !query.trim() || o.order_number.toLowerCase().includes(query.trim().toLowerCase())
  );

  const totals = (orders.data ?? [])
    .filter((o) => o.status !== "cancelled")
    .reduce((acc, o) => {
      acc.total += Number(o.grand_total);
      acc.paid += Number(o.paid_amount);
      acc.remaining += Math.max(0, Number(o.grand_total) - Number(o.paid_amount));
      return acc;
    }, { total: 0, paid: 0, remaining: 0 });

  return (
    <div className="screen">
      <h2 className="section-heading">كشف الحساب</h2>

      <div className="chip-row">
        <button className={"chip" + (tab === "orders" ? " chip-active" : "")} onClick={() => setTab("orders")}>
          الطلبيات والمدفوعات
        </button>
        <button className={"chip" + (tab === "ledger" ? " chip-active" : "")} onClick={() => setTab("ledger")}>
          حركة الحساب
        </button>
      </div>

      {tab === "orders" ? (
        orders.loading ? <Spinner />
        : orders.error ? <ErrorState message={orders.error} onRetry={orders.reload} />
        : !orders.data?.length ? (
          <div className="center-state">
            <Package size={26} /><p>لا توجد طلبات بعد</p>
            <button className="btn-primary" onClick={onShop}>ابدأ التسوق</button>
          </div>
        ) : (
          <>
            <div className="stat-grid">
              <div className="stat-box"><span>إجمالي المشتريات</span><b>{money(totals.total)}</b></div>
              <div className="stat-box"><span>المدفوع</span><b>{money(totals.paid)}</b></div>
              <div className="stat-box stat-box-debt"><span>المتبقي عليك</span><b>{money(totals.remaining)}</b></div>
            </div>

            <div className="search-bar">
              <Search size={16} />
              <input placeholder="ابحث برقم الفاتورة..." value={query}
                onChange={(e) => setQuery(e.target.value)} dir="ltr" style={{ textAlign: "right" }} />
              {query && <button className="search-clear" onClick={() => setQuery("")}><X size={15} /></button>}
            </div>

            <div className="ledger-list">
              {filtered.map((o) => {
                const remaining = Math.max(0, Number(o.grand_total) - Number(o.paid_amount));
                const cancelled = o.status === "cancelled";
                return (
                  <button className={"order-row" + (cancelled ? " order-row-cancelled" : "")}
                          key={o.id} onClick={() => onOpenOrder(o.id)}>
                    <div className="order-row-top">
                      <span className="order-row-id">{o.order_number}</span>
                      <span className={"status-pill" + (cancelled ? " status-pill-cancelled" : "")}>
                        {customerStatusLabel(o.status)}
                      </span>
                    </div>
                    <span className="order-row-meta">
                      {String(o.created_at).slice(0, 10)} · {PAYMENT_LABELS[o.payment_method]}
                    </span>
                    <div className="order-row-bottom">
                      <span className={remaining > 0 && !cancelled ? "pay-status pay-status-amber" : "pay-status pay-status-success"}>
                        {cancelled ? "ملغاة" : remaining > 0 ? "بانتظار التحصيل" : "مدفوعة بالكامل"}
                      </span>
                      <span className="order-row-total">{money(o.grand_total)}</span>
                    </div>
                    {remaining > 0 && !cancelled && (
                      <span className="order-row-remaining">المتبقي: {money(remaining)}</span>
                    )}
                  </button>
                );
              })}
            </div>
          </>
        )
      ) : (
        ledger.loading ? <Spinner />
        : ledger.error ? <ErrorState message={ledger.error} onRetry={ledger.reload} />
        : (
          <div className="items-report">
            {(ledger.data ?? []).map((e, i) => (
              <div className="item-tx-row" key={i}>
                <span className="item-tx-date">{String(e.entry_date).slice(0, 10)}</span>
                <span className="item-tx-qty">{e.label}</span>
                <span className="item-tx-price">
                  {Number(e.debit) > 0 ? `مدين ${money(e.debit)}` : `دائن ${money(e.credit)}`}
                </span>
              </div>
            ))}
            {!ledger.data?.length && <div className="center-state"><p>لا توجد حركة بعد</p></div>}
          </div>
        )
      )}
    </div>
  );
}

/* ===================================================================
   تفاصيل الطلبية
=================================================================== */

const COMPANY = {
  name: "جملة",
  address: "سوق الجمعة، 20 رمضان — مقابل مسجد الحويشات، طرابلس",
  phone: "+218 91 336 3363",
};

// يهرّب أي نص أدخله مستخدم (اسم صنف...) قبل حقنه داخل HTML — بدونها، نص فيه
// كود <script> ممكن يتنفّذ وقت فتح الفاتورة كـ PDF
function esc(s) {
  return String(s ?? "").replace(/[&<>"']/g, (c) => (
    { "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" }[c]
  ));
}

function buildCustomerInvoiceHTML(order) {
  const items = (order.suppliers ?? []).flatMap((s) => s.items ?? []);
  const rows = items.map((i, n) => `<tr><td>${n + 1}</td><td>${esc(i.product_name)}</td><td>${esc(i.unit)}</td>
    <td>${i.qty_confirmed ?? i.qty_requested}</td><td>${Number(i.unit_price).toFixed(2)}</td>
    <td>${Number(i.line_total).toFixed(2)}</td></tr>`).join("");

  return `<!DOCTYPE html><html dir="rtl" lang="ar"><head><meta charset="utf-8"/>
<title>فاتورة — ${order.order_number}</title><style>
@import url('https://fonts.googleapis.com/css2?family=Cairo:wght@700;800&family=Tajawal:wght@400;500;700&display=swap');
*{box-sizing:border-box}body{font-family:'Tajawal',sans-serif;color:#181d2a;margin:0;padding:32px;background:#f4f5f9}
.sheet{max-width:860px;margin:0 auto;background:#fff;border-radius:20px;padding:36px;
  box-shadow:0 1px 3px rgba(24,29,42,.06),0 1px 2px rgba(24,29,42,.04)}
header{display:flex;justify-content:space-between;border-bottom:2px solid #ecedf2;padding-bottom:20px;margin-bottom:24px}
.brand small{display:block;font-family:'Tajawal',sans-serif;font-weight:500;font-size:14px;color:#6b7280;margin-top:6px}
.doc-title{font-family:'Cairo',sans-serif;font-weight:800;font-size:22px;text-align:left;margin:0}
.doc-meta{font-size:13.5px;font-weight:500;color:#6b7280;text-align:left;margin-top:8px;line-height:2}
table{width:100%;border-collapse:separate;border-spacing:0;margin-bottom:20px;border-radius:14px;overflow:hidden;
  box-shadow:0 1px 3px rgba(24,29,42,.06)}
thead th{background:#181d2a;color:#fff;padding:12px;font-size:13px;font-family:'Cairo',sans-serif;font-weight:700;text-align:right}
tbody td{border-bottom:1px solid #ecedf2;padding:12px;font-size:14.5px;font-weight:500;color:#181d2a;background:#fff}
tbody tr:last-child td{border-bottom:none}
tbody td:first-child{width:36px;text-align:center;font-weight:700;color:#6b7280}
.totals{width:300px;margin-right:auto}
.totals table{margin:0;box-shadow:none;border-radius:14px;overflow:hidden}
.totals td{font-size:14.5px;font-weight:600;color:#6b7280;background:#f4f5f9;border-bottom:1px solid #ecedf2}
.totals td:last-child{font-family:'Cairo',sans-serif;font-weight:800;text-align:left;color:#181d2a}
.totals tr.grand td{background:#ff6a1a;color:#fff;font-size:17px;border-bottom:none}
.totals tr.grand td:last-child{color:#fff}
footer{margin-top:34px;border-top:1px solid #ecedf2;padding-top:16px;font-size:12.5px;font-weight:500;color:#6b7280;
display:flex;justify-content:space-between}
.pdf-toolbar{position:sticky;top:0;z-index:10;display:flex;gap:10px;justify-content:center;
  background:#181d2a;padding:12px;margin-bottom:20px;border-radius:14px}
.pdf-toolbar button{background:#ff6a1a;color:#fff;border:none;padding:10px 20px;font-family:'Cairo',sans-serif;
  font-weight:700;font-size:13px;cursor:pointer;border-radius:999px}
.pdf-toolbar button:last-child{background:rgba(255,255,255,.15)}
@media print{.pdf-toolbar{display:none}body{background:#fff;padding:0}.sheet{box-shadow:none;border-radius:0}}
</style></head><body>
<div class="pdf-toolbar">
  <button onclick="window.print()">🖨️ طباعة / حفظ PDF</button>
  <button onclick="window.close()">✕ إغلاق</button>
</div>
<div class="sheet">
<header><div><img src="${LOGO_FULL}" alt="${COMPANY.name}" style="height:50px;width:auto;display:block;margin-bottom:12px"/>
<p style="margin:0;font-size:13.5px;font-weight:500;color:#6b7280;line-height:1.9">${COMPANY.address}<br/>${COMPANY.phone}</p></div>
<div><h2 class="doc-title">فاتورة</h2><div class="doc-meta">
رقم الفاتورة: <strong style="color:#181d2a">${order.order_number}</strong><br/>التاريخ: ${String(order.created_at).slice(0, 10)}<br/>
طريقة الدفع: ${PAYMENT_LABELS[order.payment_method]}</div></div></header>
<table><thead><tr><th>#</th><th>الصنف</th><th>الوحدة</th><th>الكمية</th><th>السعر</th><th>الإجمالي</th></tr></thead>
<tbody>${rows}</tbody></table>
<div class="totals"><table>
<tr><td>مجموع الأصناف</td><td>${money(order.items_subtotal)}</td></tr>
<tr><td>تكلفة التوصيل</td><td>${money(order.delivery_fee)}</td></tr>
<tr class="grand"><td>الإجمالي</td><td>${money(order.grand_total)}</td></tr></table></div>
<footer><span>${COMPANY.name} — منصة تجارة الجملة</span><span>${COMPANY.phone}</span></footer>
</div></body></html>`;
}

function downloadCustomerInvoice(order) {
  const w = window.open("", "_blank");
  if (!w) return alert("يرجى السماح بالنوافذ المنبثقة لعرض الفاتورة.");
  w.document.open(); w.document.write(buildCustomerInvoiceHTML(order)); w.document.close();
}

function OrderDetailView({ orderId }) {
  const { data: order, loading, error, reload } = useFetch((signal) => api.order(orderId, signal), [orderId]);

  if (loading) return <Spinner />;
  if (error) return <ErrorState message={error} onRetry={reload} />;
  if (!order) return null;

  const remaining = Math.max(0, Number(order.grand_total) - Number(order.paid_amount));

  return (
    <div className="screen">
      <div className="order-detail-head">
        <span className="order-row-id">{order.order_number}</span>
        <span className="status-pill">{customerStatusLabel(order.status)}</span>
      </div>
      <p className="order-row-meta">
        {String(order.created_at).slice(0, 10)} · {PAYMENT_LABELS[order.payment_method]}
      </p>
      <button className="link-btn" style={{ marginBottom: 10 }} onClick={() => downloadCustomerInvoice(order)}>
        📄 عرض / تنزيل الفاتورة PDF
      </button>

      {order.payment_method === "deferred" && order.deferred_due_date && (
        <div className="note-block">
          <span className="note-label">تفاصيل البيع الآجل</span>
          <p>
            يُدفع {money(order.deposit_due_at_delivery)} عند الاستلام · المتبقي {money(remaining)}
            {" "}يستحق بتاريخ {String(order.deferred_due_date).slice(0, 10)}
          </p>
        </div>
      )}

      {order.suppliers.map((s) => (
        <div className="invoice-block" key={s.id}>
          <div className="invoice-head">
            <span>{s.supplier_name}</span>
            <span className="status-pill">{statusLabel(s.status)}</span>
          </div>
          {s.items.map((i) => (
            <div className="invoice-line" key={i.id}>
              <span className="invoice-line-name">
                {i.product_name} <i>× {i.qty_confirmed ?? i.qty_requested}</i>
                {i.availability === "partial" && <em className="tag tag-amber"> متوفر جزئيًا</em>}
                {i.availability === "out" && <em className="tag tag-muted"> غير متوفر</em>}
              </span>
              <span className="invoice-line-price">{money(i.line_total)}</span>
            </div>
          ))}
          {s.supplier_note && <div className="supplier-note-shown">ملاحظتك: {s.supplier_note}</div>}
          <div className="invoice-sub"><span>مجموع الفاتورة</span><b>{money(s.subtotal)}</b></div>
        </div>
      ))}

      <div className="summary-block">
        <div className="summary-row"><span>مجموع الأصناف</span><span>{money(order.items_subtotal)}</span></div>
        <div className="summary-row"><span>تكلفة التوصيل</span><span>{money(order.delivery_fee)}</span></div>
        <div className="summary-row"><span>المدفوع</span><span>{money(order.paid_amount)}</span></div>
        <div className="summary-row summary-total"><span>الإجمالي</span><b>{money(order.grand_total)}</b></div>
      </div>

      <h2 className="subsection-heading">سجل حالة الطلبية</h2>
      <div className="items-report">
        {order.history
          .map((h) => ({ ...h, label: customerStatusLabel(h.to_status) }))
          .filter((h, i, arr) => i === 0 || h.label !== arr[i - 1].label)
          .map((h, i) => (
            <div className="item-tx-row" key={i}>
              <span className="item-tx-date">{String(h.changed_at).slice(0, 10)}</span>
              <span className="item-tx-qty">{h.label}</span>
              <span className="item-tx-price">{h.changed_by_name}</span>
            </div>
          ))}
      </div>

      {["delivered", "closed"].includes(order.status) && (
        <PostDeliveryPanel order={order} />
      )}

      <h2 className="subsection-heading">تواصل مع الدعم</h2>
      <CustomerChatPanel orderId={order.id} />
    </div>
  );
}

function ReceiptsPanel({ orderId }) {
  const { data, loading, error } = useFetch(() => api.orderReceipts(orderId), [orderId]);
  if (loading) return <Spinner label="جارٍ تحميل الإيصالات…" />;
  if (error) return <ErrorState message={error} />;
  if (!data?.length) return null;

  return (
    <>
      <h2 className="subsection-heading">إيصالات الإغلاق</h2>
      <div className="items-report">
        {data.map((r) => (
          <div className="item-tx-row" key={r.id}>
            <span className="item-tx-date">{String(r.issued_at).slice(0, 10)}</span>
            <span className="item-tx-qty">
              {r.receipt_number} — مدفوع {money(r.amount_paid)}{Number(r.amount_remaining) > 0 ? ` · متبقٍ ${money(r.amount_remaining)}` : " · مسدَّد بالكامل"}
            </span>
          </div>
        ))}
      </div>
    </>
  );
}

const FEEDBACK_ABOUT_LABELS = { delivery: "التوصيل", supplier: "المورد", quality: "جودة الأصناف", service: "الخدمة" };

function PostDeliveryPanel({ order }) {
  const [tab, setTab] = useState("feedback");
  return (
    <>
      <ReceiptsPanel orderId={order.id} />
      <div className="chip-row">
        <button className={"chip" + (tab === "feedback" ? " chip-active" : "")} onClick={() => setTab("feedback")}>تقييم الطلبية</button>
        <button className={"chip" + (tab === "return" ? " chip-active" : "")} onClick={() => setTab("return")}>طلب إرجاع</button>
      </div>
      {tab === "feedback" ? <FeedbackForm order={order} /> : <ReturnForm order={order} />}
    </>
  );
}

function FeedbackForm({ order }) {
  const [rating, setRating] = useState(0);
  const [about, setAbout] = useState("delivery");
  const [comment, setComment] = useState("");
  const [sent, setSent] = useState(false);
  const submit = useAction(() => api.submitFeedback({
    orderId: order.id, rating: rating || undefined, about, comment: comment.trim() || undefined,
  }));

  if (sent) {
    return <div className="note-block"><span className="note-label">شكرًا لك</span><p>تم إرسال تقييمك — سيراجعه فريق جملة.</p></div>;
  }

  return (
    <div className="supplier-note-block">
      <div className="star-row">
        {[1, 2, 3, 4, 5].map((n) => (
          <button key={n} className="star-btn" onClick={() => setRating(n)} aria-label={`${n} نجوم`}>
            <Star size={22} fill={n <= rating ? "currentColor" : "none"} />
          </button>
        ))}
      </div>
      <label className="field-label">بخصوص</label>
      <div className="chip-row">
        {Object.entries(FEEDBACK_ABOUT_LABELS).map(([k, l]) => (
          <button key={k} className={"chip" + (about === k ? " chip-active" : "")} onClick={() => setAbout(k)}>{l}</button>
        ))}
      </div>
      <textarea className="note-input" placeholder="اكتب ملاحظتك أو شكواك هنا..." value={comment} onChange={(e) => setComment(e.target.value)} />
      {submit.error && <p className="field-error">{submit.error}</p>}
      <button className="btn-primary" disabled={submit.pending}
        onClick={() => submit.run().then(() => setSent(true)).catch(() => {})}>
        {submit.pending ? "جارٍ الإرسال…" : "إرسال التقييم"}
      </button>
    </div>
  );
}

function ReturnForm({ order }) {
  const allItems = order.suppliers.flatMap((s) => s.items.map((i) => ({ ...i, supplierId: s.supplier_id })));
  const [picked, setPicked] = useState({});   // { itemId: qty }
  const [reason, setReason] = useState("");
  const [sent, setSent] = useState(false);
  const submit = useAction(() => api.createReturn({
    orderId: order.id, reason: reason.trim(),
    items: Object.entries(picked).filter(([, qty]) => qty > 0).map(([orderItemId, qty]) => ({ orderItemId, qty })),
  }));

  if (sent) {
    return <div className="note-block"><span className="note-label">تم استلام طلبك</span><p>سيتواصل معك فريق جملة لتأكيد الإرجاع.</p></div>;
  }

  const anyPicked = Object.values(picked).some((q) => q > 0);

  return (
    <div className="supplier-note-block">
      <div className="items-block" style={{ marginBottom: 12 }}>
        {allItems.map((i) => (
          <div className="item-line" key={i.id}>
            <div className="item-line-main">
              <span className="item-name">{i.product_name}</span>
              <span className="item-supplier">الكمية المشتراة: {i.qty_confirmed ?? i.qty_requested}</span>
            </div>
            <input className="qty-input" type="number" min="0" max={i.qty_confirmed ?? i.qty_requested}
              value={picked[i.id] || ""} placeholder="0"
              onChange={(e) => setPicked((p) => ({ ...p, [i.id]: Math.max(0, Number(e.target.value) || 0) }))} />
          </div>
        ))}
      </div>
      <label className="field-label">سبب الإرجاع</label>
      <textarea className="note-input" placeholder="مثال: وصل الصنف تالفًا" value={reason} onChange={(e) => setReason(e.target.value)} />
      {submit.error && <p className="field-error">{submit.error}</p>}
      <button className="btn-primary" disabled={!anyPicked || !reason.trim() || submit.pending}
        onClick={() => submit.run().then(() => setSent(true)).catch(() => {})}>
        {submit.pending ? "جارٍ الإرسال…" : "إرسال طلب الإرجاع"}
      </button>
    </div>
  );
}

function CustomerChatPanel({ orderId }) {
  const { data, loading, error, reload } = useFetch(() => api.orderMessages(orderId), [orderId]);
  const [draft, setDraft] = useState("");
  const send = useAction(() => api.sendOrderMessage(orderId, { body: draft.trim() }));

  function submit() {
    if (!draft.trim()) return;
    send.run().then(() => { setDraft(""); reload(); }).catch(() => {});
  }

  return (
    <div className="chat-panel">
      <div className="chat-thread">
        {loading ? <Spinner label="جارٍ التحميل…" />
         : error ? <ErrorState message={error} onRetry={reload} />
         : !data?.length ? <p className="chat-empty">راسلنا هنا لو عندك أي استفسار بخصوص هذه الطلبية.</p>
         : data.map((m, i) => (
            <div className={"chat-bubble " + (m.sender_type === "customer" ? "chat-bubble-user" : "chat-bubble-support")} key={i}>
              <span>{m.body}</span>
              <span className="chat-time">{new Date(m.created_at).toLocaleTimeString("ar", { hour: "2-digit", minute: "2-digit" })}</span>
            </div>
          ))}
      </div>
      <div className="chat-input-row">
        <input className="chat-input" placeholder="اكتب رسالتك..." value={draft}
          onChange={(e) => setDraft(e.target.value)} onKeyDown={(e) => e.key === "Enter" && submit()} />
        <button className="chat-send" onClick={submit} disabled={send.pending} aria-label="إرسال"><Send size={17} /></button>
      </div>
      {send.error && <p className="field-error">{send.error}</p>}
    </div>
  );
}

